package bookstore

import "sort"

// groupPrice holds the total price, in cents, of a group of the given size
// after applying the group discount to every book in the group.
//
//	1 book:  1 x $8.00 = $8.00
//	2 books: 2 x $7.60 = $15.20
//	3 books: 3 x $7.20 = $21.60
//	4 books: 4 x $6.40 = $25.60
//	5 books: 5 x $6.00 = $30.00
var groupPrice = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the total price, in cents, of the given basket of books,
// applying the largest possible discount.
//
// The basket is reduced to how many copies of each of the five books it
// contains, sorted from most to least common. Books are then removed in
// groups of distinct titles, largest group first. The only non-obvious
// decision is whether to take a group of five or a group of four when all
// five titles are present: a group of five plus a group of three costs
// $51.60, while two groups of four cost $51.20. Whenever the three most
// common titles are strictly more numerous than the next most common one,
// taking a group of four now keeps the remaining books balanced enough to
// form another group of four, so that is the cheaper choice.
func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		counts[b-1]++
	}
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })

	price := 0
	for {
		if counts[0] == 0 {
			break
		}
		// The group can contain at most one copy of each title, so its
		// size is the number of distinct titles still in the basket.
		group := 0
		for _, c := range counts {
			if c == 0 {
				break
			}
			group++
		}
		if group == 5 && counts[2] > counts[3] {
			group = 4
		}
		price += groupPrice[group]
		for i := 0; i < group; i++ {
			counts[i]--
		}
		sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })
	}
	return price
}

